    }
    for (Node node = head; node != null; node = node.next.next) {
        Node copy = new Node(node.val);
        copy.next = node.next;
        node.next = copy;
    }

    for (Node node = head; node != null; node = node.next.next) {
        Node copy = node.next;
        copy.random = node.random != null ? node.random.next : null;
    }
    Node copyHead = head.next;
